import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"大有","description":"周易集解 - 大有","frontmatter":{"title":"大有","description":"周易集解 - 大有"},"headers":[],"relativePath":"zh/classics/jijie/014.md","filePath":"zh/classics/jijie/014.md"}'),l={name:"zh/classics/jijie/014.md"};function n(d,a,t,s,p,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="大有" tabindex="-1">大有 <a class="header-anchor" href="#大有" aria-label="Permalink to “大有”">​</a></h1><h2 id="大有-1" tabindex="-1">大有 <a class="header-anchor" href="#大有-1" aria-label="Permalink to “大有”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>大有，元亨。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：與人同者，物必歸焉，故受之以大有。</p><p>崔憬曰：以欲從人，物必歸己，所以成大有。</p><p>虞翻曰：與比旁通。柔得尊位大中，應天而時行，故元亨也。</p><p>姚規曰：互體有兌，兌為澤，位在秋也。乾則施生，澤則流潤，離則長茂，秋則成收，大富有也。大有則元亨矣。</p><p>鄭玄曰：六五體離，處乾之上，猶大臣有聖明之德，代君為政，處其位，有其事而理之也。元亨者，又是能長群臣以善，使嘉會禮通，若周公攝政，朝諸侯於明堂是也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：大有，柔得尊位，大中而上下應之，曰大有。其德剛健而文明，應乎天而時行，是以元亨。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>王弼曰：處尊以柔，居中以大。體無二陰，以陰而分其應，上下應之，靡所不納，大有之義也。</p><p>虞翻曰：謂五，以日應乾而行於天也。時，謂四時也。大有亨。比初動成震為春；至二，兌為秋。至三，離為夏。坎為冬。故曰時行。以乾亨坤，是以元亨。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：火在天上，大有。君子以遏惡揚善，順天休命。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：謂夏，火王在天，萬物並生，故曰大有也。</p><p>虞翻曰：遏，絕。揚，舉也。乾為揚善，坤為遏惡，為順。以乾滅坤。體夬，揚於王庭。故｢遏惡揚善｣。乾為天休，二變時，巽為命，故｢順天休命｣。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九：無交害，匪咎，艱則無咎。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：害謂四。四離火，為惡人，故無交害。初動，震為交。比坤為害。匪，非也。艱，難，謂陽動比初成屯。屯，難也。變得位，艱則無咎。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：大有初九，無交害也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：害，謂四。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二：大車以載，有攸往，無咎。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：比坤為大車，乾來積上，故大車以載。往，謂之五。二失位，變得正應五。故｢有攸往無咎｣矣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：大車以載，積中不敗也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：乾為大車，故曰｢大車以載｣。體剛履中，可以任重，有應於五，故所積皆中而不敗也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三：公用亨於天子，小人弗克。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：天子謂五。三，公位也。小人謂四。二變得位，體鼎象。故｢公用亨於天子｣。四折鼎足，覆公餗，故小人不克也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：公用亨於天子，小人害也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：小人，謂四也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，匪其彭，無咎。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：匪，非也。其位尫。足尫，體行不正，四失位，折震足，故尫。變而得正，故無咎。尫或作彭，作旁聲，字之誤。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：匪其彭，無咎，明辯晢也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：皙之離，故｢明辯晢也｣。四在乾則尫；在坤為鼠；在震噬胏得金矢；在巽折鼎足，在坎為鬼方；在離焚死；在艮旅於處，言無所容；在兌睽孤孚厲。三百八十四爻，獨無所容也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五：厥孚交如，威如吉。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：孚，信也。發而孚二，故交如。乾稱威，發得位，故威如吉。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：厥孚交如，信以發志也。威如之吉，易而無備也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：其體文明，其德中順。信發乎志，以覃於物。物懷其德，以信應君。君物交信，厥孚交如也。為卦之主，有威不用，唯行簡易，無所防備。物感其德，翻更畏威，威如之吉也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九：自天祐之，吉，無不利。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：謂乾也。祐，助也。大有通比，坤為自，乾為天，兌為右，故｢自天祐之｣。比坤為順，乾為信。天之所助者順，人之所助者信。履信思順，又以尚賢，故｢自天祐之，吉無不利｣。</p><p>王弼曰：餘爻皆乘剛，已獨乘柔順也。五為信德，而已履焉，履信者也。居豐富之代，物不累心，高尚其志，尚賢者也。爻有三德，盡夫助道，故《繫辭》具焉也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：大有上吉，自天祐也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：上九悅五，以柔處尊，而自謙損。尚賢奉已，上下應之，為乾所祐，故吉且利也。</p>',69)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
